35	    keyBits: 128,
36	    ivBits: 128,
37	    name: "AES-CTR",
38	  }),
39	  "aes-256-cbc": /* @__PURE__ */ Object.freeze({
40	    keyBits: 256,
41	    ivBits: 128,
42	    name: "AES-CBC",
43	  }),
44	  sha256: /* @__PURE__ */ Object.freeze({
45	    keyBits: 256,
46	    ivBits: 128,
47	    name: "SHA-256",
48	  }),
49	}) as Record<string, { keyBits: number; ivBits: number; name: string }>;
