  it("throttles idleTimeout reseals to once per half window", async () => {
    const t0 = Date.parse("2030-01-01T00:00:00Z");
    vi.useFakeTimers({ toFake: ["Date"], now: t0 });
    // Every seal runs exactly one `subtle.encrypt` (see `iron-crypto.ts`)
