/**
 * Upper bound on `extraUnsealPasswords`. Every entry can cost a full PBKDF2
 * derivation for each request that carries an invalid cookie.
 */
const MAX_EXTRA_UNSEAL_PASSWORDS = 4;

/**
 * Reject an invalid `extraUnsealPasswords` list. Runs first in `getSession`:
 * an error raised inside `unsealSession` would be swallowed and the session
 * silently reset.
 */
function assertExtraUnsealPasswords(config: SessionConfig): void {
  const extra = config.extraUnsealPasswords;
  if (!extra) {
    return;
  }
  if (extra.length > MAX_EXTRA_UNSEAL_PASSWORDS) {
    throw new Error(
      `extraUnsealPasswords accepts at most ${MAX_EXTRA_UNSEAL_PASSWORDS} passwords`,
    );
  }
  const sealOptions = { ...sealDefaults, ...config.seal };
  const minLength = Math.max(
    sealOptions.encryption.minPasswordlength,
    sealOptions.integrity.minPasswordlength,
  );
  for (const password of extra) {
    if (!password || password.length < minLength) {
      throw new Error(`Each extraUnsealPasswords entry must be at least ${minLength} characters`);
    }
  }
}

/**
 * Unseal with one password. A session sealed with the legacy 1 PBKDF2 iteration
 * fails HMAC verification with the current count, so retry once with the legacy
 * count.
 */
async function unsealWithPassword(
  sealed: string,
  password: string,
  sealOptions: SealOptions,
  config: SessionConfig,
): Promise<Partial<Session>> {
  try {
    return (await unseal(sealed, password, sealOptions)) as Partial<Session>;
  } catch (error) {
    // TODO: Remove this fallback (and `legacySealFallback`) in v3. Removing it
    // in a v2 release would invalidate existing sessions sealed with 1 iteration.
    // Sessions sealed before the default PBKDF2 iterations were raised from 1
    // to 8192 fail HMAC verification; retry with the legacy count so existing
    // sessions survive the upgrade (getSession reseals them with the current
    // options).
    if (
      config.legacySealFallback === false ||
      sealOptions.integrity.iterations === 1 ||
      !(error instanceof Error) ||
      error.message !== "Bad hmac value"
    ) {
      throw error;
    }
    const unsealed = (await unseal(sealed, password, {
      ...sealOptions,
      encryption: { ...sealOptions.encryption, iterations: 1 },
      integrity: { ...sealOptions.integrity, iterations: 1 },
    })) as Partial<Session>;
    if (unsealed) {
      (unsealed as any)[kLegacySeal] = true;
    }
    return unsealed;
  }
}

