    const olderPassword = "senha-mais-antiga-com-32-caracteres";
    const unknownPassword = "senha-de-outro-ambiente-com-32-chars";

    const rotConfig = (extraUnsealPasswords?: string[]): SessionConfig => ({
      name: "h3-rot",
      password: currentPassword,
      extraUnsealPasswords,
      generateId: () => "rot-new",
    });

    const legacyOptions = {
      ...sealDefaults,
      encryption: { ...sealDefaults.encryption, iterations: 1 },
      integrity: { ...sealDefaults.integrity, iterations: 1 },
    };

    const registerSessionRoute = (path: string, config: SessionConfig) => {
      t.app.all(path, async (event) => {
        const session = await useSession(event, config);
        if (event.req.method === "POST") {
          await session.update((await readBody(event)) as any);
        }
        return { id: session.id, data: session.data };
      });
    };

    const sealWith = (password: string, data: Record<string, unknown>, options = sealDefaults) =>
      seal({ id: "old", createdAt: Date.now(), data }, password, options);

    const sealedCookie = (res: Response) => {
      const cookie = res.headers.getSetCookie().find((c) => c.startsWith("h3-rot="))!;
      return decodeURIComponent(cookie.match(/=([^;]+)/)![1]);
    };

    it("seals with password only", async () => {
      registerSessionRoute("/rot", rotConfig([oldPassword]));
      const res = await t.fetch("/rot", {
        method: "POST",
        body: JSON.stringify({ user: "alice" }),
      });
      const sealed = sealedCookie(res);
      await expect(unseal(sealed, oldPassword, sealDefaults)).rejects.toThrow("Bad hmac value");
      expect(await unseal(sealed, currentPassword, sealDefaults)).toMatchObject({
        data: { user: "alice" },
      });
    });

    it("tries password, then each extra password, in order", async () => {
      const sealed = await sealWith(oldPassword, { user: "alice" });
      const config = { ...rotConfig([olderPassword, oldPassword]), legacySealFallback: false };
      const deriveBits = vi.spyOn(crypto.subtle, "deriveBits");
      const importKey = vi.spyOn(crypto.subtle, "importKey");
      try {
        const unsealed = await unsealSession({} as H3Event, config, sealed);
        expect(unsealed).toMatchObject({ data: { user: "alice" } });
        // One PBKDF2 import per attempt, in order. A failed attempt costs one
        // derivation (the HMAC), the opening attempt costs two (HMAC and decrypt).
        const attempted = importKey.mock.calls
          .filter(([, , algorithm]) => (algorithm as Algorithm).name === "PBKDF2")
          .map(([, keyData]) => new TextDecoder().decode(keyData as BufferSource));
        expect(attempted).toEqual([currentPassword, olderPassword, oldPassword]);
        expect(deriveBits).toHaveBeenCalledTimes(4);
      } finally {
        deriveBits.mockRestore();
        importKey.mockRestore();
      }
    });

    it("keeps the same derivations without extra passwords", async () => {
      const sealed = await sealWith(currentPassword, { user: "alice" });
      const deriveBits = vi.spyOn(crypto.subtle, "deriveBits");
      try {
        await unsealSession({} as H3Event, rotConfig(), sealed);
        expect(deriveBits).toHaveBeenCalledTimes(2);
      } finally {
        deriveBits.mockRestore();
      }
    });

    it("starts a new session when no password opens the cookie", async () => {
      registerSessionRoute("/rot", rotConfig([oldPassword]));
      const sealed = await sealWith(unknownPassword, { user: "mallory" });
      const res = await t.fetch("/rot", { headers: { Cookie: `h3-rot=${sealed}` } });
      expect(await res.json()).toMatchObject({ id: "rot-new", data: {} });
    });

    it("reseals a legacy session sealed with an extra password", async () => {
      registerSessionRoute("/rot", rotConfig([oldPassword]));
      const sealed = await sealWith(oldPassword, { user: "alice" }, legacyOptions);
      const res = await t.fetch("/rot", { headers: { Cookie: `h3-rot=${sealed}` } });
      expect(await res.json()).toMatchObject({ id: "old", data: { user: "alice" } });

      const resealed = sealedCookie(res);
      expect(await unseal(resealed, currentPassword, sealDefaults)).toMatchObject({ id: "old" });
      await expect(unseal(resealed, oldPassword, sealDefaults)).rejects.toThrow("Bad hmac value");
    });

    it("reseals with password once, then stops resealing", async () => {
      registerSessionRoute("/rot", rotConfig([oldPassword]));
      const sealed = await sealWith(oldPassword, { user: "alice" });
      const res1 = await t.fetch("/rot", { headers: { Cookie: `h3-rot=${sealed}` } });
      expect(await res1.json()).toMatchObject({ id: "old", data: { user: "alice" } });

      const resealed = sealedCookie(res1);
      await expect(unseal(resealed, oldPassword, sealDefaults)).rejects.toThrow("Bad hmac value");

      const res2 = await t.fetch("/rot", { headers: { Cookie: `h3-rot=${resealed}` } });
      expect(await res2.json()).toMatchObject({ id: "old", data: { user: "alice" } });
      expect(res2.headers.getSetCookie()).toHaveLength(0);
    });

    it("does not reseal header sessions opened with an extra password", async () => {
      registerSessionRoute("/rot", rotConfig([oldPassword]));
      const sealed = await sealWith(oldPassword, { user: "alice" });
      const res = await t.fetch("/rot", { headers: { "x-h3-rot-session": sealed } });
      expect(await res.json()).toMatchObject({ id: "old", data: { user: "alice" } });
      expect(res.headers.getSetCookie()).toHaveLength(0);
    });

    it("treats a session past maxAge as invalid when opened with an extra password", async () => {
      registerSessionRoute("/rot", { ...rotConfig([oldPassword]), maxAge: 60 });
      const sealed = await seal(
        { id: "old", createdAt: Date.now() - 120_000, data: { user: "alice" } },
        oldPassword,
        sealDefaults,
      );
      const res = await t.fetch("/rot", { headers: { Cookie: `h3-rot=${sealed}` } });
      expect(await res.json()).toMatchObject({ id: "rot-new", data: {} });
    });

    it("reseals a chunked session sealed with an extra password", async () => {
      const big = "x".repeat(5000);
      registerSessionRoute("/rot-old", { name: "h3-rot", password: oldPassword });
      registerSessionRoute("/rot", rotConfig([oldPassword]));

      const seeded = await t.fetch("/rot-old", {
        method: "POST",
        body: JSON.stringify({ big }),
      });
      const seededCookies = seeded.headers.getSetCookie();
      expect(seededCookies.length).toBeGreaterThan(1);
      const cookieHeader = seededCookies.map((c) => c.split(";")[0]).join("; ");

      const res = await t.fetch("/rot", { headers: { Cookie: cookieHeader } });
      expect((await res.json()).data.big).toBe(big);
      expect(res.headers.getSetCookie().length).toBeGreaterThan(1);
    });

    it("rejects an invalid extraUnsealPasswords list when the session is read", async () => {
      const invalid = [
        [""],
        ["x".repeat(31)],
        Array.from({ length: 5 }, (_, i) => `${currentPassword}-${i}`),
      ];
      for (const list of invalid) {
        await expect(getSession({} as H3Event, rotConfig(list))).rejects.toThrow(
          "extraUnsealPasswords",
        );
      }
    });

    it("accepts an empty or missing extraUnsealPasswords list", async () => {
      registerSessionRoute("/rot-empty", rotConfig([]));
      registerSessionRoute("/rot-missing", rotConfig());
      expect((await t.fetch("/rot-empty")).status).toBe(200);
      expect((await t.fetch("/rot-missing")).status).toBe(200);
    });
  });
});
